#include "dwg2dxf/dx_iface.h"
#include "dwg2dxf/dx_data.h"
#include <cstring>
#include <fstream>
#include <iostream>
#include <sstream>
#include <stdexcept>

class DxIfaceMaterialReferenceTestAccess {
public:
    static bool qualified(const dx_iface& adapter,std::uint32_t selected) {
        const auto row=adapter.m_dxfMLineStyles.find(selected);
        if (!adapter.m_dxfMLineStylesInspected || !adapter.m_dxfMLineLinetypesInspected
            || adapter.m_dxfMLineConsumerInspected!=3u || adapter.m_dxfMLineConsumers.size()!=2u
            || row==adapter.m_dxfMLineStyles.end() || !row->second.baseline
            || !row->second.linetypesBound || !row->second.countChanged || !row->second.geometryChanged || !row->second.referencesChanged || !row->second.dictionaryOrigin
            || !row->second.dictionaryOrigin->bodyMatched || !row->second.dictionaryOrigin->stateComplete
            || !row->second.dictionaryOrigin->originBound) return false;
        for (const auto& consumer:adapter.m_dxfMLineConsumers)
            if (!consumer.second.original || consumer.second.model.styleHandle==selected
                || consumer.second.original->styleHandle==selected) return false;
        return true;
    }
};

void text(std::ostream& out,const std::string& value) { out<<value.size()<<':'<<value; }
void number(std::ostream& out,double value) {
    std::uint64_t bits=0;static_assert(sizeof(bits)==sizeof(value),"double bits");
    std::memcpy(&bits,&value,sizeof(bits));out<<bits<<';';
}
void variant(std::ostream& out,const DRW_Variant& value) {
    out<<value.code()<<':'<<value.type()<<':';
    switch(value.type()) {
    case DRW_Variant::STRING: text(out,*value.content.s);break;
    case DRW_Variant::INTEGER:out<<value.i_val();break;
    case DRW_Variant::INTEGER64:out<<value.i64_val();break;
    case DRW_Variant::DOUBLE:number(out,value.d_val());break;
    case DRW_Variant::COORD:number(out,value.coord()->x);number(out,value.coord()->y);number(out,value.coord()->z);break;
    case DRW_Variant::BINARY:out<<value.binary()->size()<<':';for(const auto byte:*value.binary())out<<static_cast<unsigned>(byte)<<',';break;
    case DRW_Variant::INVALID:throw std::runtime_error("unexpected invalid source variant");
    }
    out<<';';
}
std::string snapshot(const DRW_MLineStyle& value,const DRW_RawDxfObject& raw) {
    std::ostringstream out;
    const auto& base=static_cast<const DRW_TableEntry&>(value);
    out<<base.tType<<';'<<base.handle<<';'<<base.parentHandle<<';'<<base.flags<<';';text(out,base.name);
    out<<base.xDictHandle<<';'<<base.hasDataStorageBinaryData()<<';';
    for(const auto handle:base.reactorHandles)out<<handle<<',';
    for(const auto* item:base.extData){if(!item)throw std::runtime_error("null xdata");variant(out,*item);}
    for(const auto& group:base.appData){out<<"app;";for(const auto& item:group)variant(out,item);}
    out<<value.flags<<';'<<value.fillColor<<';'<<value.fillColor24<<';'
        <<static_cast<unsigned>(value.fillColorMethod)<<';'<<static_cast<unsigned>(value.fillColorFlags)<<';'<<value.fillColorDwgIndex<<';';
    text(out,value.description);text(out,value.fillColorName);text(out,value.fillColorBookName);
    number(out,value.startAngle);number(out,value.endAngle);
    out<<value.elements.size()<<';'<<value.validateDxfRecord()<<';';
    for(const auto& item:value.elements) {
        number(out,item.offset);out<<item.color<<';'<<item.color24<<';'<<static_cast<unsigned>(item.colorMethod)<<';'
            <<static_cast<unsigned>(item.colorFlags)<<';'<<item.colorDwgIndex<<';'<<item.linetypeIndex<<';'<<item.linetypeHandle<<';';
        text(out,item.colorName);text(out,item.colorBookName);text(out,item.linetype);
    }
    text(out,raw.name);out<<raw.handle<<';'<<raw.parentHandle<<';'<<raw.m_version<<';'<<raw.hasRawValues<<';'
        <<raw.groups.size()<<';'<<raw.rawValues.size()<<';'<<raw.m_retainedTextLease.get()<<';';
    for(const auto& field:raw.groups)variant(out,field);
    for(const auto& spelling:raw.rawValues)text(out,spelling);
    return out.str();
}
std::string contents(const std::string& path) {
    std::ifstream in(path,std::ios::binary);return {(std::istreambuf_iterator<char>(in)),{}};
}
int main(int argc,char** argv) {
    if(argc!=5)return 2;
    const std::string mode=argv[3],format=argv[4];
    if(mode!="append"||(format!="asc"&&format!="bin"))return 2;
    dx_iface adapter;dx_data data;if(!adapter.fileImport(argv[1],&data,false))return 2;
    DRW_MLineStyle* selected=nullptr;
    for(const auto& dictionary:data.dictionaries)for(const auto& entry:dictionary.m_entries)
        if(entry.m_name=="PeerRetarget")for(auto& style:data.mLineStyles)
            if(style.handle==entry.m_handle&&style.parentHandle==dictionary.handle){if(selected)return 2;selected=&style;}
    if(!selected||selected->elements.size()!=2u||selected->elements[0].offset!=1.25)return 2;
    DRW_RawDxfObject* raw=nullptr;
    for(auto& object:data.rawNamedResourceObjects)if(object.handle==selected->handle&&object.name=="MLINESTYLE"){
        if(raw)return 2;raw=&object;
    }
    if(!raw||!raw->hasRawValues||raw->groups.size()!=raw->rawValues.size())return 2;
    std::size_t slot=raw->groups.size();
    for(std::size_t index=0;index<raw->groups.size();++index)
        if(raw->groups[index].code()==49){slot=index;break;}
    if(slot==raw->groups.size()||raw->groups[slot].type()!=DRW_Variant::DOUBLE||raw->groups[slot].d_val()!=1.25)return 2;
    unsigned consumers=0;
    const auto visit=[&](const dx_ifaceBlock* block) {
        if(!block)return true;
        for(const auto* entity:block->ent)if(entity&&entity->eType==DRW::MLINE){
            const auto* value=dynamic_cast<const DRW_MLine*>(entity);
            if(!value||value->styleHandle==selected->handle)return false;
            ++consumers;
        }
        return true;
    };
    if(!visit(data.mBlock))return 2;
    for(const auto* block:data.blocks)if(!visit(block))return 2;
    if(consumers!=2u)return 2;
    auto element=selected->elements.front();element.offset=2.25;element.color=7;selected->elements.push_back(element);
    const auto before=snapshot(*selected,*raw);
    const std::string sentinel="UNUSED_STYLE_OFFSET_ATOMIC_DESTINATION";
    {std::ofstream out(argv[2],std::ios::binary);out<<sentinel;}
    const bool accepted=adapter.fileExport(argv[2],data.sourceVersion,format=="bin",&data,false,true,
        dx_dxfSourceTextPolicy::RequireValidSource,DRW::DxfTextWritePolicy::RequireLossless);
    const bool preserved=before==snapshot(*selected,*raw);
    const bool sentinelPreserved=contents(argv[2])==sentinel;
    const bool qualified=accepted&&DxIfaceMaterialReferenceTestAccess::qualified(adapter,selected->handle);
    std::cout<<"{\"mode\":\""<<mode<<"\",\"format\":\""<<format<<"\",\"accepted\":"<<accepted
        <<",\"selectedCallerSnapshotPreserved\":"<<preserved<<",\"sentinelPreserved\":"<<sentinelPreserved
        <<",\"selectedDefinitionAuthorityAndOutputQualified\":"<<qualified
        <<",\"otherOriginalMlineConsumers\":"<<consumers<<",\"selectedTypedOffset\":"<<selected->elements[0].offset
        <<",\"selectedRawOffset\":"<<raw->groups[slot].d_val()<<"}\n";
    return preserved&&accepted&&qualified&&!sentinelPreserved?0:1;
}
